<script setup lang="ts">
import {dateTime as time} from '../../utils/update-center'
import ImageViewer from './ImageViewer.vue'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import ConsolePagination from '@orangezh1/qisvc-console-ui/components/ConsolePagination'
import ConsoleActionConfirmationDialog from '@orangezh1/qisvc-console-ui/components/ConsoleActionConfirmationDialog'
export type Material={id:string;name:string;kind:'image'|'video'|'file';mime:string;bytes:number;source:string;provider:string;groupId:string|null;visibility:string;status:string;version:number;createdAt:string;url:string;thumbnail:string|null}
type Group={id:string;name:string;kind:string;version:number}
type Listing={items:Material[];total:number;groups:Group[];canManage:boolean;canUpload:boolean;policy:{label:string;revisionId:string|null;maxFileMb:number;external:boolean;blockedReason?:string}}
const props=withDefaults(defineProps<{purpose?:'library'|'policy'|'site'|'account'|'tenant'|'profile';kind?:'image'|'video'|'file';picker?:boolean;fullHeight?:boolean;portal?:'admin'|'tenant';endpoint?:string}>(),{purpose:'library',picker:false,portal:'admin',endpoint:'/admin/materials'})
const emit=defineEmits<{refreshing:[value:boolean]}>(),selected=defineModel<Material[]>('selected',{default:()=>[]}),connection=useApi(props.portal),notices=useToast()
const base=props.endpoint,lifetime=new AbortController(),toast={add:(options:Parameters<typeof notices.add>[0])=>{if(!disposed)notices.add(options)}}
const auth={api:<T>(url:string,method:'GET'|'POST'|'PUT'|'DELETE'='GET',body?:unknown,options?:{signal?:AbortSignal})=>connection.api<T>(url,method,body,{signal:options?.signal?AbortSignal.any([lifetime.signal,options.signal]):lifetime.signal})}
const kind=props.picker||props.kind?ref<'image'|'video'|'file'>(props.kind||'image'):useRouteTab<'image'|'video'|'file'>('image',['image','video','file'],'type'),group=ref('all'),source=ref('all'),q=ref(''),search=ref(''),page=ref(1),pageSize=ref(20),view=ref<'grid'|'list'>('grid'),busy=ref(false),loadAction=ref('initial'),action=ref<string|null>(null),error=ref(''),input=ref<HTMLInputElement|null>(null),uploadProgress=ref(''),broken=reactive(new Set<string>())
const params=()=>new URLSearchParams({purpose:props.purpose,kind:kind.value,group:group.value,source:source.value,q:search.value,page:String(page.value),pageSize:String(pageSize.value)})
let sequence=0,disposed=false,listController:AbortController|undefined
const initialController=new AbortController()
const initial=useAsyncData('material-browser-'+base+':'+useId(),(_nuxt,{signal})=>auth.api<Listing>(base+'?'+params(),'GET',undefined,{signal:AbortSignal.any([signal,initialController.signal])}))
const loadedData=ref<Listing|null>(null),emptyData:Listing={items:[],total:0,groups:[],canManage:false,canUpload:false,policy:{label:'',revisionId:'',maxFileMb:20,external:false}}
// The initial response stays reactive for SSR; later user actions take ownership of the listing.
const data=computed({get:()=>loadedData.value??initial.data.value??emptyData,set:(value:Listing)=>{loadedData.value=value}})
watch(()=>initial.error.value,value=>{if(value&&!disposed&&sequence===0)error.value='素材读取失败，请重试'},{immediate:true,flush:'sync'})
watch(()=>initial.status?.value,status=>{if(!disposed&&sequence===0)busy.value=status==='pending'||status==='idle'},{immediate:true,flush:'sync'})
const tabs=[{label:'图片',value:'image'},{label:'视频',value:'video'},{label:'文件',value:'file'}] as const
const sources=[{label:'全部来源',value:'all'},{label:'本地存储',value:'local'},{label:'七牛云',value:'qiniu'},{label:'阿里云 OSS',value:'oss'},{label:'腾讯云 COS',value:'cos'},{label:'历史上传',value:'legacy'}]
const accept=computed(()=>kind.value==='image'?'image/jpeg,image/png,image/webp':kind.value==='video'?'video/mp4,video/webm':undefined)
const selectable=computed(()=>data.value.items.filter(r=>r.status==='ready'))
const allSelected=computed(()=>selectable.value.length>0&&selectable.value.every(r=>selected.value.some(x=>x.id===r.id)))
const formatSize=(n:number)=>n<1024*1024?(n/1024).toFixed(1)+' KB':(n/1024/1024).toFixed(1)+' MB'
onBeforeUnmount(()=>{sequence++;disposed=true;lifetime.abort();emit('refreshing',false)})
async function load(trigger='refresh'){if(disposed)return;if(sequence===0){loadedData.value=initial.data.value??emptyData;initialController.abort()}listController?.abort();listController=new AbortController();const seq=++sequence;busy.value=true;loadAction.value=trigger;emit('refreshing',trigger==='refresh');try{const result=await auth.api<Listing>(base+'?'+params(),'GET',undefined,{signal:listController.signal});if(seq===sequence&&!disposed){data.value=result;error.value='';selected.value=selected.value.filter(r=>result.items.some(n=>n.id===r.id&&n.status==='ready'))}}catch(e){if(seq===sequence&&!disposed)error.value=e instanceof Error?e.message:'读取失败'}finally{if(seq===sequence&&!disposed){busy.value=false;emit('refreshing',false)}}}
function filter(trigger='search'){search.value=q.value.trim();page.value=1;selected.value=[];void load(trigger)}
function selectGroup(id:string){group.value=id;filter('group')}
function selectKind(value:'image'|'video'|'file'){if(kind.value!==value)kind.value=value}
watch(kind,()=>{group.value='all';filter('tab')},{flush:'sync'})
function selectRow(row:Material){if(busy.value||row.status!=='ready'||action.value)return;selected.value=selected.value.some(r=>r.id===row.id)?selected.value.filter(r=>r.id!==row.id):props.picker?[row]:[...selected.value,row]}
function selectAll(value:boolean|'indeterminate'){if(busy.value)return;selected.value=value===true?[...selectable.value]:[]}
function setPage(n:number){if(n===page.value)return;page.value=n;selected.value=[];void load('page')}
function setPageSize(n:number){if(n===pageSize.value)return;pageSize.value=n;page.value=1;selected.value=[];void load('page')}
async function upload(event:Event){const element=event.target as HTMLInputElement,files=Array.from(element.files||[]);element.value='';if(!files.length||action.value)return;if(files.length>20){toast.add({title:'每次最多上传 20 个文件',color:'error'});return}action.value='upload';let count=0;const failures:string[]=[];
  try{for(const [index,file]of files.entries()){if(disposed)break;uploadProgress.value=`${index+1} / ${files.length}`;try{if(file.size>data.value.policy.maxFileMb*1024*1024)throw Error(`超过 ${data.value.policy.maxFileMb} MB`);const query=new URLSearchParams({purpose:props.purpose,kind:kind.value,name:file.name,requestId:crypto.randomUUID(),storageRevision:data.value.policy.revisionId||'',...(props.purpose!=='profile'&&!['all','none'].includes(group.value)?{groupId:group.value}:{})});await auth.api(base+'/upload?'+query,'POST',new Blob([file],{type:'application/octet-stream'}));count++}catch(e){failures.push(file.name+'：'+(e instanceof Error?e.message:'上传失败'))}}
    if(!disposed){toast.add({title:failures.length?`成功 ${count} 个，失败 ${failures.length} 个`:`已上传 ${count} 个素材`,description:failures.slice(0,3).join('；'),color:failures.length?'warning':'success'});if(count){q.value='';search.value='';source.value='all';if(props.purpose==='profile')group.value='all'}page.value=1;await load('mutation')}
  }finally{if(!disposed){action.value=null;uploadProgress.value=''}}
}
const dialog=ref<'rename'|'group-create'|'group-rename'|null>(null),nameValue=ref(''),target=ref<Material|null>(null),targetFolder=ref<Group|null>(null),dialogError=ref(''),groupRequest=ref(''),moveOpen=ref(false),moveGroup=ref('none'),deleteOpen=ref(false),deleteRows=ref<Material[]>([]),deleteFolder=ref<Group|null>(null),preview=ref<Material|null>(null)
const dialogOpen=computed({get:()=>!!dialog.value,set:value=>{if(!value&&!action.value)dialog.value=null}})
function rename(row:Material){target.value=row;nameValue.value=row.name;dialogError.value='';dialog.value='rename'}
function editGroup(row:Group|null){targetFolder.value=row;nameValue.value=row?.name||'';dialogError.value='';groupRequest.value=crypto.randomUUID();dialog.value=row?'group-rename':'group-create'}
function askDelete(rows:Material[]){deleteRows.value=rows;deleteFolder.value=null;deleteOpen.value=true}
function groupActions(row:Group){return[[{label:'重命名',onSelect:()=>editGroup(row)},{label:'删除分组',color:'error' as const,onSelect:()=>{deleteFolder.value=row;deleteRows.value=[];deleteOpen.value=true}}]]}
async function saveName(){if(action.value)return;action.value='name';dialogError.value='';try{if(dialog.value==='rename'&&target.value)await auth.api(base+'/'+target.value.id,'PUT',{name:nameValue.value,version:target.value.version});else await auth.api(base+'/groups'+(targetFolder.value?'/'+targetFolder.value.id:''),targetFolder.value?'PUT':'POST',{name:nameValue.value,kind:kind.value,...(targetFolder.value?{version:targetFolder.value.version}:{requestId:groupRequest.value})});dialog.value=null;await load('mutation')}catch(e){dialogError.value=e instanceof Error?e.message:'保存失败'}finally{action.value=null}}
async function move(){if(action.value)return;action.value='move';try{await auth.api(base+'/move','POST',{ids:selected.value.map(r=>r.id),kind:kind.value,groupId:moveGroup.value==='none'?null:moveGroup.value});moveOpen.value=false;selected.value=[];await load('mutation');toast.add({title:'素材已移动',color:'success'})}catch(e){toast.add({title:e instanceof Error?e.message:'移动失败',color:'error'})}finally{action.value=null}}
async function remove(){if(action.value)return;action.value='delete';try{if(deleteFolder.value){const folder=deleteFolder.value;await auth.api(base+'/groups/'+folder.id,'DELETE',{version:folder.version});if(group.value===folder.id)group.value='none';toast.add({title:'分组已删除，素材已移至未分组',color:'success'})}else{const result=await auth.api<{deleted:number;failed:number}>(base+'/delete','POST',{ids:deleteRows.value.map(r=>r.id)});toast.add({title:`已删除 ${result.deleted} 项`+(result.failed?`，${result.failed} 项未完成，可重试`:''),color:result.failed?'warning':'success'})}deleteOpen.value=false;selected.value=[];await load('mutation')}catch(e){toast.add({title:e instanceof Error?e.message:'删除失败',color:'error'})}finally{action.value=null}}
defineExpose({load})
</script>
<template><section class="material-browser flex min-h-0 flex-col overflow-hidden" :class="[{'surface-card':!picker},fullHeight?'flex-1':'h-[min(65dvh,640px)]']">
  <div v-if="!props.kind" role="tablist" aria-label="素材类型" class="flex shrink-0 border-b border-default px-5"><div class="relative inline-flex gap-7"><button v-for="tab in tabs" :key="tab.value" type="button" role="tab" :aria-selected="kind===tab.value" class="w-7 shrink-0 cursor-pointer border-b-2 border-transparent py-4 text-sm transition-colors duration-200 motion-reduce:transition-none disabled:cursor-not-allowed" :class="kind===tab.value?'font-medium text-primary':'text-muted'" :disabled="!!action" @click="selectKind(tab.value)">{{tab.label}}</button><span aria-hidden="true" class="material-tab-indicator" :style="{transform:'translateX('+tabs.findIndex(tab=>tab.value===kind)*3.5+'rem)'}"/></div></div>
  <div class="flex min-h-0 flex-1 flex-col sm:flex-row">
    <aside class="flex shrink-0 flex-col border-b border-default p-3 sm:w-44 sm:border-b-0 sm:border-r">
      <div class="flex min-h-0 gap-1 overflow-auto sm:flex-col"><button v-for="folder in [{id:'all',name:'全部'},{id:'none',name:'未分组'}]" :key="folder.id" type="button" class="flex shrink-0 items-center gap-2 rounded-md px-3 py-2 text-sm" :class="group===folder.id?'bg-primary/10 text-primary':'hover:bg-elevated'" :disabled="!!action" @click="selectGroup(folder.id)"><UIcon name="i-lucide-folder" class="size-4 text-amber-400"/>{{folder.name}}</button>
        <div v-for="folder in data.groups" :key="folder.id" class="flex min-w-0 shrink-0 items-center rounded-md" :class="group===folder.id?'bg-primary/10 text-primary':'hover:bg-elevated'"><button type="button" class="flex min-w-0 flex-1 items-center gap-2 px-3 py-2 text-sm" :disabled="!!action" @click="selectGroup(folder.id)"><UIcon name="i-lucide-folder" class="size-4 shrink-0 text-amber-400"/><span class="truncate" :title="folder.name">{{folder.name}}</span></button><UDropdownMenu v-if="data.canManage" :items="groupActions(folder)"><UButton icon="i-lucide-ellipsis" color="neutral" variant="ghost" size="xs" :aria-label="folder.name+'分组操作'" :disabled="!!action"/></UDropdownMenu></div>
      </div><UButton v-if="data.canManage" class="mt-3 justify-center sm:mt-auto" color="neutral" variant="outline" icon="i-lucide-plus" :disabled="!!action" @click="editGroup(null)">添加分组</UButton>
    </aside>
    <div class="flex min-h-0 min-w-0 flex-1 flex-col p-4">
      <div class="flex flex-wrap items-center gap-2">
        <UButton v-if="data.canUpload||busy&&loadAction==='initial'" icon="i-lucide-upload" :loading="action==='upload'" :disabled="!!action||!data.canUpload||!data.policy.revisionId" @click="input?.click()">{{action==='upload'?'上传中 '+uploadProgress:'本地上传'}}</UButton>
        <template v-if="!picker&&data.canManage"><UButton color="neutral" variant="outline" :disabled="busy||!!action||!selected.length" @click="askDelete(selected)">删除</UButton><UButton color="neutral" variant="outline" :disabled="!!action||!selected.length" @click="moveGroup='none';moveOpen=true">移动</UButton></template>
        <form class="flex flex-wrap items-center gap-2" @submit.prevent="filter('search')"><USelect v-model="source" :items="sources" class="w-36" aria-label="文件来源" :disabled="!!action" @update:model-value="filter('source')"/><div class="w-44"><ConsoleInput v-model="q" placeholder="请输入名称" aria-label="素材名称" :disabled="!!action"/></div><UButton type="submit" icon="i-lucide-search" color="neutral" variant="outline" :loading="busy&&loadAction==='search'" :disabled="!!action" aria-label="搜索素材"/></form>
        <div class="flex gap-1"><UButton icon="i-lucide-list" :variant="view==='list'?'soft':'ghost'" color="neutral" aria-label="列表视图" @click="view='list'"/><UButton icon="i-lucide-layout-grid" :variant="view==='grid'?'soft':'ghost'" color="neutral" aria-label="网格视图" @click="view='grid'"/></div>
      </div>
      <UAlert v-if="data.policy.blockedReason" color="warning" :title="data.policy.blockedReason" class="mt-3"/><div class="my-3 flex flex-wrap items-center justify-between gap-2 text-xs text-muted"><UCheckbox v-if="!picker" :model-value="allSelected" label="当页全选" :disabled="!!action" @update:model-value="selectAll"/><span v-else>已选择 {{selected.length}} / 1 <UButton v-if="selected.length" size="xs" variant="link" @click="selected=[]">清空</UButton></span><span v-if="data.canUpload">{{props.purpose==='profile'?'新上传头像仅本人可见 · ':''}}{{data.policy.label}} · 最大 {{data.policy.maxFileMb}} MB</span></div>
      <input ref="input" type="file" class="hidden" :accept="accept" multiple aria-label="上传素材文件" :disabled="!!action" @change="upload"/>
      <UAlert v-if="error" color="error" :title="error" class="mb-4"><template #actions><UButton color="neutral" variant="outline" :loading="busy&&loadAction==='retry'" @click="load('retry')">重试</UButton></template></UAlert>
      <div class="min-h-0 flex-1 overflow-auto">
      <div v-if="busy&&loadAction==='initial'" class="material-loading-grid" aria-label="正在读取素材" role="status"><div v-for="n in 8" :key="n" class="material-loading-tile"><div/><span/><small/></div></div>
      <div v-else-if="data.items.length&&view==='grid'" class="grid content-start gap-4" style="grid-template-columns:repeat(auto-fill,minmax(136px,1fr))">
        <article v-for="row in data.items" :key="row.id" class="min-w-0 rounded-lg border p-2" :class="selected.some(r=>r.id===row.id)?'border-primary bg-primary/5':'border-default'">
          <button type="button" class="relative flex aspect-square w-full items-center justify-center overflow-hidden rounded-md bg-elevated/50" :disabled="busy||row.status!=='ready'||!!action" :aria-label="'选择 '+row.name" :aria-pressed="selected.some(r=>r.id===row.id)" @click="selectRow(row)"><img v-if="row.kind==='image'&&row.thumbnail&&!broken.has(row.id)&&row.status==='ready'" :src="row.thumbnail" :alt="row.name" class="size-full object-contain" loading="lazy" @error="broken.add(row.id)"/><UIcon v-else :name="row.kind==='video'?'i-lucide-video':row.kind==='image'?'i-lucide-images':'i-lucide-file-text'" class="size-10 text-muted"/><span v-if="selected.some(r=>r.id===row.id)" class="absolute right-1 top-1 grid size-5 place-items-center rounded-full bg-primary text-white"><UIcon name="i-lucide-check" class="size-3"/></span></button>
          <p class="mt-2 truncate text-sm" :title="row.name">{{row.name}}</p><p class="mt-1 text-xs text-muted">{{formatSize(row.bytes)}}{{row.status!=='ready'?' · '+(row.status==='uploading'?'上传中':'待清理'):''}}</p>
          <div class="mt-1 flex flex-wrap gap-2"><UButton v-if="row.status==='ready'" class="px-0" size="xs" variant="link" @click="preview=row">查看</UButton><UButton v-if="data.canManage&&row.status==='ready'" class="px-0" size="xs" variant="link" :disabled="!!action" @click="rename(row)">重命名</UButton><UButton v-if="data.canManage" class="px-0" size="xs" variant="link" color="error" :disabled="!!action" @click="askDelete([row])">删除</UButton></div>
        </article>
      </div>
      <div v-else-if="data.items.length" class="overflow-x-auto"><table class="w-full min-w-[580px] text-left text-sm"><thead class="bg-elevated/50 text-muted"><tr><th class="p-3">选择</th><th class="p-3">名称</th><th class="p-3">大小</th><th class="p-3">来源</th><th class="p-3">上传时间</th><th class="p-3">操作</th></tr></thead><tbody><tr v-for="row in data.items" :key="row.id" class="border-b border-default"><td class="p-3"><UCheckbox :aria-label="'选择 '+row.name" :model-value="selected.some(r=>r.id===row.id)" :disabled="row.status!=='ready'||!!action" @update:model-value="selectRow(row)"/></td><td class="max-w-64 truncate p-3" :title="row.name">{{row.name}}</td><td class="p-3">{{formatSize(row.bytes)}}</td><td class="p-3">{{row.source}}</td><td class="p-3 text-xs">{{time(row.createdAt)}}</td><td class="p-3"><div class="flex gap-3"><UButton v-if="row.status==='ready'" variant="link" size="xs" class="px-0" @click="preview=row">查看</UButton><UButton v-if="data.canManage&&row.status==='ready'" variant="link" size="xs" class="px-0" :disabled="!!action" @click="rename(row)">重命名</UButton><UButton v-if="data.canManage" variant="link" size="xs" color="error" class="px-0" :disabled="!!action" @click="askDelete([row])">删除</UButton></div></td></tr></tbody></table></div>
      <div v-else class="grid h-full min-h-20 place-content-center text-center"><UIcon name="i-lucide-images" class="mx-auto mb-3 size-9 text-muted"/><p class="text-sm text-muted">{{error?'素材暂不可用':busy?'读取中…':'暂无素材'}}</p></div>
      </div><div class="mt-auto shrink-0 pt-4"><p v-if="selected.length" class="mb-2 text-xs text-muted">已选 {{selected.length}} 项</p><ConsolePagination always-visible :page="page" :page-size="pageSize" :total="data.total" :page-size-options="[10,20,50]" @update:page="setPage" @update:page-size="setPageSize"/></div>
    </div>
  </div>
  <UModal v-model:open="dialogOpen" :title="dialog==='rename'?'重命名素材':dialog==='group-create'?'添加分组':'重命名分组'" :dismissible="!action" :close="!action"><template #body><form id="material-name-form" class="space-y-4" @submit.prevent="saveName"><UFormField label="名称" required><ConsoleInput v-model="nameValue" required :maxlength="dialog==='rename'?180:40" :disabled="!!action"/></UFormField><UAlert v-if="dialogError" color="error" :title="dialogError"/></form></template><template #footer><div class="flex w-full justify-end gap-3"><UButton color="neutral" variant="outline" :disabled="!!action" @click="dialog=null">取消</UButton><UButton type="submit" form="material-name-form" :loading="action==='name'">保存</UButton></div></template></UModal>
  <UModal v-model:open="moveOpen" title="移动素材" :dismissible="!action" :close="!action"><template #body><UFormField label="目标分组"><USelect v-model="moveGroup" :items="[{label:'未分组',value:'none'},...data.groups.map(g=>({label:g.name,value:g.id}))]" class="w-full" :disabled="!!action"/></UFormField></template><template #footer><div class="flex w-full justify-end gap-3"><UButton color="neutral" variant="outline" :disabled="!!action" @click="moveOpen=false">取消</UButton><UButton :loading="action==='move'" @click="move">确定移动</UButton></div></template></UModal>
  <ConsoleActionConfirmationDialog v-model:open="deleteOpen" :title="deleteFolder?'删除分组？':'删除所选素材？'" :description="deleteFolder?'分组内的素材会移至未分组，不会删除文件。':portal==='tenant'?'删除后不能再从当前范围访问或选择这些文件。':'删除后不能再从素材库选择这些文件；已保存的头像、Logo 等图片不受影响。'" :subject="deleteFolder?.name||deleteRows.length+' 项素材'" confirm-label="确认删除" color="error" :loading="action==='delete'" @confirm="remove"/>
  <ImageViewer :open="preview?.kind==='image'" :src="preview?.kind==='image'?preview.url:null" :label="preview?.name||'图片'" @update:open="(value:boolean)=>{if(!value)preview=null}"/>
  <UModal :open="!!preview&&preview.kind!=='image'" :title="preview?.name||'素材预览'" :ui="{content:'sm:max-w-3xl'}" @update:open="(value:boolean)=>{if(!value)preview=null}"><template #body><template v-if="preview"><img v-if="preview.kind==='image'" :src="preview.url" :alt="preview.name" class="mx-auto max-h-[60vh] max-w-full object-contain"/><video v-else-if="preview.kind==='video'" :src="preview.url" controls preload="metadata" class="max-h-[60vh] w-full"/><div v-else class="py-10 text-center"><UIcon name="i-lucide-file-text" class="size-12 text-muted"/><p class="mt-3">{{preview.name}}</p></div><div class="mt-5 flex justify-between text-xs text-muted"><span>{{preview.source}} · {{formatSize(preview.bytes)}}</span><UButton :to="preview.url" external target="_blank" variant="link" size="sm">{{preview.kind==='file'?'下载文件':'打开原文件'}}</UButton></div></template></template></UModal>
</section></template>

<style scoped>
.material-tab-indicator{position:absolute;bottom:0;left:0;width:1.75rem;height:2px;background:var(--ui-primary);transition:transform 240ms cubic-bezier(.2,.8,.2,1);pointer-events:none}
@media(prefers-reduced-motion:reduce){.material-tab-indicator{transition:none}}
.material-loading-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(136px,1fr));gap:16px}.material-loading-tile{padding:8px;border:1px solid var(--ui-border);border-radius:8px}.material-loading-tile>div{aspect-ratio:1;border-radius:6px;background:var(--ui-bg-elevated)}.material-loading-tile>span,.material-loading-tile>small{display:block;height:12px;background:var(--ui-bg-elevated);border-radius:3px;margin-top:10px;width:70%}.material-loading-tile>small{width:40%;height:10px}
</style>
